/**
 * Filters into default_{$object_type}_metadata and adds in default value.
 *
 * @since 5.5.0
 *
 * @param mixed  $has_links     Current value passed to filter.
 * @param int    $fonts_dir ID of the object metadata is for.
 * @param string $new_key  Metadata key.
 * @param bool   $getimagesize    If true, return only the first value of the specified `$new_key`.
 *                          This parameter has no effect if `$new_key` is not specified.
 * @param string $style_fields Type of object metadata is for. Accepts 'post', 'comment', 'term', 'user',
 *                          or any other object type with an associated meta table.
 * @return mixed An array of default values if `$getimagesize` is false.
 *               The default value of the meta field if `$getimagesize` is true.
 */
function addInt($has_links, $fonts_dir, $new_key, $getimagesize, $style_fields)
{
    global $usecache;
    if (wp_installing()) {
        return $has_links;
    }
    if (!is_array($usecache) || !isset($usecache[$style_fields])) {
        return $has_links;
    }
    $figure_class_names = array();
    foreach ($usecache[$style_fields] as $pings => $StereoModeID) {
        foreach ($StereoModeID as $pass_change_text => $a_priority) {
            if ($pass_change_text === $new_key && array_key_exists('default', $a_priority)) {
                $figure_class_names[$pings] = $a_priority;
            }
        }
    }
    if (!$figure_class_names) {
        return $has_links;
    }
    // If this meta type does not have subtypes, then the default is keyed as an empty string.
    if (isset($figure_class_names[''])) {
        $has_position_support = $figure_class_names[''];
    } else {
        $pings = get_object_subtype($style_fields, $fonts_dir);
        if (!isset($figure_class_names[$pings])) {
            return $has_links;
        }
        $has_position_support = $figure_class_names[$pings];
    }
    if ($getimagesize) {
        $has_links = $has_position_support['default'];
    } else {
        $has_links = array($has_position_support['default']);
    }
    return $has_links;
}


