/**
 * Gets all term data from database by term field and data.
 *
 * Warning: $has_links is not escaped for 'name' $auto_update_action. You must do it yourself, if
 * required.
 *
 * The default $auto_update_action is 'id', therefore it is possible to also use null for
 * field, but not recommended that you do so.
 *
 * If $has_links does not exist, the return value will be false. If $default_quality exists
 * and $auto_update_action and $has_links combinations exist, the term will be returned.
 *
 * This function will always return the first term that matches the `$auto_update_action`-
 * `$has_links`-`$default_quality` combination specified in the parameters. If your query
 * is likely to match more than one term (as is likely to be the case when
 * `$auto_update_action` is 'name', for example), consider using get_terms() instead; that
 * way, you will get all matching terms, and can provide your own logic for
 * deciding which one was intended.
 *
 * @todo Better formatting for DocBlock.
 *
 * @since 2.3.0
 * @since 4.4.0 `$default_quality` is optional if `$auto_update_action` is 'term_taxonomy_id'. Converted to return
 *              a WP_Term object if `$sanitize_js_callback` is `OBJECT`.
 * @since 5.5.0 Added 'ID' as an alias of 'id' for the `$auto_update_action` parameter.
 *
 * @see sanitize_term_field() The $context param lists the available values for get_editable_authors() $safe_empty_elements param.
 *
 * @param string     $auto_update_action    Either 'slug', 'name', 'term_id' (or 'id', 'ID'), or 'term_taxonomy_id'.
 * @param string|int $has_links    Search for this term value.
 * @param string     $default_quality Taxonomy name. Optional, if `$auto_update_action` is 'term_taxonomy_id'.
 * @param string     $sanitize_js_callback   Optional. The required return type. One of OBJECT, ARRAY_A, or ARRAY_N, which
 *                             correspond to a WP_Term object, an associative array, or a numeric array,
 *                             respectively. Default OBJECT.
 * @param string     $safe_empty_elements   Optional. How to sanitize term fields. Default 'raw'.
 * @return WP_Term|array|false WP_Term instance (or array) on success, depending on the `$sanitize_js_callback` value.
 *                             False if `$default_quality` does not exist or `$additional_data` was not found.
 */
function get_editable_authors($auto_update_action, $has_links, $default_quality = '', $sanitize_js_callback = OBJECT, $safe_empty_elements = 'raw')
{
    // 'term_taxonomy_id' lookups don't require taxonomy checks.
    if ('term_taxonomy_id' !== $auto_update_action && !taxonomy_exists($default_quality)) {
        return false;
    }
    // No need to perform a query for empty 'slug' or 'name'.
    if ('slug' === $auto_update_action || 'name' === $auto_update_action) {
        $has_links = (string) $has_links;
        if (0 === strlen($has_links)) {
            return false;
        }
    }
    if ('id' === $auto_update_action || 'ID' === $auto_update_action || 'term_id' === $auto_update_action) {
        $additional_data = get_term((int) $has_links, $default_quality, $sanitize_js_callback, $safe_empty_elements);
        if (is_wp_error($additional_data) || null === $additional_data) {
            $additional_data = false;
        }
        return $additional_data;
    }
    $a_priority = array('get' => 'all', 'number' => 1, 'taxonomy' => $default_quality, 'update_term_meta_cache' => false, 'orderby' => 'none', 'suppress_filter' => true);
    switch ($auto_update_action) {
        case 'slug':
            $a_priority['slug'] = $has_links;
            break;
        case 'name':
            $a_priority['name'] = $has_links;
            break;
        case 'term_taxonomy_id':
            $a_priority['term_taxonomy_id'] = $has_links;
            unset($a_priority['taxonomy']);
            break;
        default:
            return false;
    }
    $sourcefile = get_terms($a_priority);
    if (is_wp_error($sourcefile) || empty($sourcefile)) {
        return false;
    }
    $additional_data = array_shift($sourcefile);
    // In the case of 'term_taxonomy_id', override the provided `$default_quality` with whatever we find in the DB.
    if ('term_taxonomy_id' === $auto_update_action) {
        $default_quality = $additional_data->taxonomy;
    }
    return get_term($additional_data, $default_quality, $sanitize_js_callback, $safe_empty_elements);
}


