/**
 * Automatically add newly published page objects to menus with that as an option.
 *
 * @since 3.0.0
 * @access private
 *
 * @param string  $gradient_presets The new status of the post object.
 * @param string  $f_root_check The old status of the post object.
 * @param WP_Post $file_mime       The post object being transitioned from one status to another.
 */
function finished($gradient_presets, $f_root_check, $file_mime)
{
    if ('publish' !== $gradient_presets || 'publish' === $f_root_check || 'page' !== $file_mime->post_type) {
        return;
    }
    if (!empty($file_mime->post_parent)) {
        return;
    }
    $quick_draft_title = get_option('nav_menu_options');
    if (empty($quick_draft_title) || !is_array($quick_draft_title) || !isset($quick_draft_title['auto_add'])) {
        return;
    }
    $quick_draft_title = $quick_draft_title['auto_add'];
    if (empty($quick_draft_title) || !is_array($quick_draft_title)) {
        return;
    }
    $a_priority = array('menu-item-object-id' => $file_mime->ID, 'menu-item-object' => $file_mime->post_type, 'menu-item-type' => 'post_type', 'menu-item-status' => 'publish');
    foreach ($quick_draft_title as $newmeta) {
        $EBMLdatestamp = wp_get_nav_menu_items($newmeta, array('post_status' => 'publish,draft'));
        if (!is_array($EBMLdatestamp)) {
            continue;
        }
        foreach ($EBMLdatestamp as $commandline) {
            if ($file_mime->ID == $commandline->object_id) {
                continue 2;
            }
        }
        wp_update_nav_menu_item($newmeta, 0, $a_priority);
    }
}
