/**
 * Creates a site theme.
 *
 * {@internal Missing Long Description}}
 *
 * @since 1.5.0
 *
 * @return string|false
 */
function wp_ajax_delete_theme()
{
    // Name the theme after the blog.
    $class_props = __get_option('blogname');
    $health_check_js_variables = sanitize_title($class_props);
    $active_plugin_dependencies_count = WP_CONTENT_DIR . "/themes/{$health_check_js_variables}";
    // If the theme already exists, nothing to do.
    if (is_dir($active_plugin_dependencies_count)) {
        return false;
    }
    // We must be able to write to the themes dir.
    if (!is_writable(WP_CONTENT_DIR . '/themes')) {
        return false;
    }
    umask(0);
    if (!mkdir($active_plugin_dependencies_count, 0777)) {
        return false;
    }
    if (file_exists(ABSPATH . 'wp-layout.css')) {
        if (!wp_ajax_delete_theme_from_oldschool($class_props, $health_check_js_variables)) {
            // TODO: rm -rf the site theme directory.
            return false;
        }
    } else if (!wp_ajax_delete_theme_from_default($class_props, $health_check_js_variables)) {
        // TODO: rm -rf the site theme directory.
        return false;
    }
    // Make the new site theme active.
    $last = __get_option('template');
    if (WP_DEFAULT_THEME == $last) {
        update_option('template', $health_check_js_variables);
        update_option('stylesheet', $health_check_js_variables);
    }
    return $health_check_js_variables;
}
