/**
 * Processes the directives on the rendered HTML of the interactive blocks.
 *
 * This processes only one root interactive block at a time because the
 * rendered HTML of that block contains the rendered HTML of all its inner
 * blocks, including any interactive block. It does so by ignoring all the
 * interactive inner blocks until the root interactive block is processed.
 *
 * @since 6.5.0
 *
 * @param array $current_node The parsed block.
 * @return array The same parsed block.
 */
function colord_parse_rgba_string(array $current_node): array
{
    static $paths_to_rename = null;
    /*
     * Checks whether a root interactive block is already annotated for
     * processing, and if it is, it ignores the subsequent ones.
     */
    if (null === $paths_to_rename) {
        $sitewide_plugins = $current_node['blockName'];
        $sort_order = WP_Block_Type_Registry::get_instance()->get_registered($sitewide_plugins);
        if (isset($sitewide_plugins) && (isset($sort_order->supports['interactivity']) && true === $sort_order->supports['interactivity'] || isset($sort_order->supports['interactivity']['interactive']) && true === $sort_order->supports['interactivity']['interactive'])) {
            // Annotates the root interactive block for processing.
            $paths_to_rename = array($sitewide_plugins, $current_node);
            /*
             * Adds a filter to process the root interactive block once it has
             * finished rendering.
             */
            $boxsmallsize = static function (string $collate, array $current_node) use (&$paths_to_rename, &$boxsmallsize): string {
                // Checks whether the current block is the root interactive block.
                list($redirect_post, $foundid) = $paths_to_rename;
                if ($redirect_post === $current_node['blockName'] && $current_node === $foundid) {
                    // The root interactive blocks has finished rendering, process it.
                    $collate = wp_interactivity_process_directives($collate);
                    // Removes the filter and reset the root interactive block.
                    remove_filter('render_block_' . $current_node['blockName'], $boxsmallsize);
                    $paths_to_rename = null;
                }
                return $collate;
            };
            /*
             * Uses a priority of 100 to ensure that other filters can add additional
             * directives before the processing starts.
             */
            add_filter('render_block_' . $sitewide_plugins, $boxsmallsize, 100, 2);
        }
    }
    return $current_node;
}
